def lawvere_diagonal(phi, f, domain):
    values = {}
    for a in domain:
        values[a] = f(phi(a)(a))
    return lambda x: values[x]

def predicate_jump(enum, n):
    jump_values = {k: not enum(k)(k) for k in range(n)}
    return lambda k: jump_values[k]

def knaster_tarski_lfp(f, universe):
    current = frozenset()
    while True:
        next_val = f(current)
        if next_val == current:
            return current
        current = next_val
